                "starterCode": "function romanToInt(s) {\n  const map = { I: 1, V: 5, X: 10, L: 50, C: 100 };\n  let total = 0, prev = 0;\n  for (let i = s.length - 1; i >= 0; i--) {\n    const curr = map[s[i].toUpperCase()] || 0;\n    if (curr < prev) total -= curr;\n    else total += curr;\n    prev = curr;\n  }\n  return total;\n}",
