                "instructions": "Write a function `parseQueryString(queryString)` that parses a URL query string (e.g. `'name=John&age=25'`) into a JavaScript object `{ name: 'John', age: '25' }`.",
                "starterCode": "function parseQueryString(queryString) {\n  const result = {};\n  if (!queryString) return result;\n  const cleaned = queryString.startsWith('?') ? queryString.slice(1) : queryString;\n  cleaned.split('&').forEach(pair => {\n    if (!pair) return;\n    const [k, v] = pair.split('=');\n    result[decodeURIComponent(k)] = decodeURIComponent(v || '');\n  });\n  return result;\n}",
